import re

_REF_PATTERN = re.compile(r"\$\{([^}]*)\}")


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    last_key: tuple[str, str] | None = None

    def parse_value(value_part: str) -> str:
        n = len(value_part)
        i = 0
        while i < n and value_part[i] in " \t":
            i += 1
        if i < n and value_part[i] == '"':
            j = i + 1
            while j < n and value_part[j] != '"':
                j += 1
            if j >= n:
                raise ValueError("unterminated double-quoted value")
            value = value_part[i + 1:j]
            remainder = value_part[j + 1:].strip()
            if remainder and remainder[0] not in ";#":
                raise ValueError("unexpected text after double-quoted value")
            return value
        comment_index = None
        i = 0
        while i < n:
            ch = value_part[i]
            if ch in ";#" and i > 0 and value_part[i - 1] in " \t":
                comment_index = i
                break
            i += 1
        if comment_index is not None:
            value = value_part[:comment_index]
        else:
            value = value_part
        return value.strip()

    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped[0] in ";#":
            continue
        if stripped[0] == "[" and stripped[-1] == "]":
            current_section = stripped[1:-1].strip()
            sections.setdefault(current_section, {})
            last_key = None
            continue
        if line and line[0] in " \t":
            if last_key is None:
                raise ValueError("continuation line without a preceding key line")
            section, key = last_key
            sections[section][key] += "\n" + stripped
            continue
        if current_section is None:
            raise ValueError("key line before any section header")
        equal_idx = line.find("=")
        colon_idx = line.find(":")
        sep_idx = -1
        if equal_idx != -1 and colon_idx != -1:
            sep_idx = equal_idx if equal_idx < colon_idx else colon_idx
        elif equal_idx != -1:
            sep_idx = equal_idx
        elif colon_idx != -1:
            sep_idx = colon_idx
        if sep_idx == -1:
            raise ValueError("malformed line: missing '=' or ':' separator")
        key = line[:sep_idx].strip().lower()
        if not key:
            raise ValueError("empty key name")
        value = parse_value(line[sep_idx + 1:])
        sections.setdefault(current_section, {})[key] = value
        last_key = (current_section, key)

    default_values = sections.get("DEFAULT", {})

    def resolve(section: str, key: str, visiting: set[tuple[str, str]]) -> str:
        if section not in sections:
            raise KeyError(section)
        if (section, key) in visiting:
            raise ValueError("circular interpolation")
        if key in sections[section]:
            raw = sections[section][key]
        elif "DEFAULT" in sections and key in sections["DEFAULT"]:
            raw = sections["DEFAULT"][key]
        else:
            raise KeyError(key)
        visiting.add((section, key))
        try:
            def replace(match: re.Match[str]) -> str:
                ref = match.group(1)
                if ":" in ref:
                    ref_section, ref_key = ref.split(":", 1)
                else:
                    ref_section, ref_key = section, ref
                return resolve(ref_section, ref_key, visiting)
            return _REF_PATTERN.sub(replace, raw)
        finally:
            visiting.discard((section, key))

    result: dict[str, dict[str, str]] = {}
    for section in sections:
        if section == "DEFAULT":
            continue
        result[section] = {}
        for key in sections[section]:
            result[section][key] = resolve(section, key, set())
        for key in default_values:
            if key not in result[section]:
                result[section][key] = resolve(section, key, set())
    return result
