def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    values = sorted(set(nums))
    parts: list[str] = []
    i = 0
    n = len(values)

    while i < n:
        start = values[i]
        j = i
        while j + 1 < n and values[j + 1] == values[j] + 1:
            j += 1
        end = values[j]

        if end - start >= 2:
            parts.append(f"{start}..{end}")
        else:
            parts.extend(str(x) for x in range(start, end + 1))

        i = j + 1

    return ",".join(parts)
