from decimal import Decimal, InvalidOperation


def _parse_amount(value) -> Decimal | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    cleaned = text.replace("$", "").replace(",", "").strip()
    if not cleaned:
        return None
    try:
        return Decimal(cleaned)
    except InvalidOperation:
        return None


def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    aggregated: dict[str, list] = {}

    for row in rows:
        raw_customer = row.get("customer")
        if not isinstance(raw_customer, str):
            continue
        customer = raw_customer.strip()
        if not customer:
            continue

        amount = _parse_amount(row.get("amount"))
        if amount is None:
            continue

        key = customer.lower()
        if key not in aggregated:
            aggregated[key] = [customer, Decimal(0)]
        aggregated[key][1] += amount

    ranked: list[tuple[str, float]] = [
        (name, float(total.quantize(Decimal("0.01"))))
        for name, total in aggregated.values()
    ]
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return ranked[:n]
